/** Ordered gallery image URLs for a service slug (basePath-aware), or [] if none. */
export function serviceGallery(slug: string | null | undefined): string[] {
  if (!slug) return [];
  const base = process.env.NEXT_PUBLIC_BASE_PATH || "";
  return (RAW_GALLERY[slug] || []).map((p) => `${base}${p}`);
}

/** Slugs that have at least one client-provided image. */
export const SERVICE_SLUGS_WITH_IMAGES = Object.keys(RAW_GALLERY);
